/* ── CLOCK ── */
function pad(n){return String(n).padStart(2,'0')}
function updateClock(){
  const now=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Hong_Kong'}));
  const h=pad(now.getHours()),m=pad(now.getMinutes()),s=pad(now.getSeconds());
  const el=document.getElementById('ck-t');
  if(el) el.innerHTML=`<span id="ck-h">${h}</span>:<span id="ck-m">${m}</span>:<span id="ck-s">${s}</span>`;
  const gt=document.getElementById('g-time');
  if(gt) gt.textContent=`${h}:${m} HKT`;
  const cd=document.getElementById('ck-date');
  if(cd) cd.textContent=now.toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short'});
}
setInterval(updateClock,1000); updateClock();

/* ── STARS ── */
const starsLayer=document.getElementById('stars-layer');
const starsCanvas=document.createElement('canvas');
starsCanvas.style.cssText='width:100%;height:100%;position:absolute;inset:0';
starsCanvas.width=window.innerWidth; starsCanvas.height=window.innerHeight;
const sc=starsCanvas.getContext('2d');
if(sc){
  Array.from({length:240},()=>({x:Math.random(),y:Math.random(),r:.3+Math.random()*1.1,a:.1+Math.random()*.55}))
    .forEach(s=>{sc.beginPath();sc.arc(s.x*starsCanvas.width,s.y*starsCanvas.height,s.r,0,Math.PI*2);sc.fillStyle=`rgba(242,237,228,${s.a})`;sc.fill()});
  if(starsLayer) starsLayer.appendChild(starsCanvas);
}

/* ── SKY ── */
const skyEl=document.getElementById('sky');
const skyColors=[
  {t:0,top:[6,8,18],bot:[4,6,14]},{t:.15,top:[22,28,58],bot:[12,16,38]},
  {t:.28,top:[65,85,148],bot:[32,45,88]},{t:.42,top:[175,128,82],bot:[95,68,45]},
  {t:.56,top:[195,152,90],bot:[125,95,55]},{t:.7,top:[168,112,72],bot:[105,68,42]},
  {t:.82,top:[108,55,78],bot:[62,32,52]},{t:.92,top:[35,18,44],bot:[16,8,26]},
  {t:1,top:[6,8,18],bot:[4,6,14]}
];
function lerpRGB(a,b,t){return a.map((v,i)=>Math.round(v+(b[i]-v)*t)).join(',')}
function getSkyColor(pct){
  let i=0;
  for(;i<skyColors.length-2&&!(pct<=skyColors[i+1].t);i++);
  const a=skyColors[i],b=skyColors[i+1]||skyColors[i];
  const f=b.t>a.t?(pct-a.t)/(b.t-a.t):1;
  return{top:lerpRGB(a.top,b.top,f),bot:lerpRGB(a.bot,b.bot,f)};
}
function updateSky(pct){
  if(!skyEl) return;
  const{top,bot}=getSkyColor(pct);
  skyEl.style.background=`linear-gradient(180deg,rgb(${top}) 0%,rgb(${bot}) 100%)`;
}
updateSky(0);

/* ── SCROLL PERCENT ── */
function onScroll(){
  const h=document.documentElement.scrollHeight-window.innerHeight;
  const pct=h>0?window.scrollY/h:0;
  const el=document.getElementById('scroll-pct-n');
  if(el) el.textContent=String(Math.round(pct*100)).padStart(2,'0');
  updateSky(pct);
  const nav=document.getElementById('nav');
  if(nav) nav.classList.toggle('scrolled',window.scrollY>50);
}
window.addEventListener('scroll',onScroll,{passive:true});

/* ── CUSTOM CURSOR ── */
const cur=document.getElementById('cur');
const curR=document.getElementById('cur-r');
let mx=0,my=0,rx=0,ry=0;
window.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;if(cur){cur.style.left=mx+'px';cur.style.top=my+'px';}});
(function animCursor(){
  rx+=(mx-rx)*.12; ry+=(my-ry)*.12;
  if(curR){curR.style.left=rx+'px';curR.style.top=ry+'px';}
  requestAnimationFrame(animCursor);
})();

/* ── GATE CANVAS ── */
const gateCanvas=document.getElementById('gate-c');
if(gateCanvas){
  gateCanvas.width=innerWidth; gateCanvas.height=innerHeight;
  const gc=gateCanvas.getContext('2d');
  if(gc){
    let particles=Array.from({length:180},()=>({
      x:Math.random()*gateCanvas.width,y:Math.random()*gateCanvas.height,
      r:.2+Math.random()*1.2,a:.04+Math.random()*.35,
      dx:(Math.random()-.5)*.18,dy:(Math.random()-.5)*.12,
      pa:Math.random()*Math.PI*2,ps:.003+Math.random()*.008
    }));
    function drawGate(){
      gc.clearRect(0,0,gateCanvas.width,gateCanvas.height);
      const t=performance.now()*.001;
      particles.forEach(p=>{
        p.x=(p.x+p.dx+gateCanvas.width)%gateCanvas.width;
        p.y=(p.y+p.dy+gateCanvas.height)%gateCanvas.height;
        const pulse=p.a*(.5+.5*Math.sin(t*p.ps*60+p.pa));
        gc.beginPath();gc.arc(p.x,p.y,p.r,0,Math.PI*2);
        gc.fillStyle=`rgba(242,237,228,${pulse})`;gc.fill();
      });
      requestAnimationFrame(drawGate);
    }
    drawGate();
    window.addEventListener('resize',()=>{gateCanvas.width=innerWidth;gateCanvas.height=innerHeight;});
  }
}

/* ── GATE ANIMATION ── */
