/* ── MODAL ── */
const modal=document.getElementById('modal');
const mInner=document.getElementById('mInner');
const mClose=document.getElementById('mClose');

function openModal(item){
  if(!modal||!mInner) return;
  let content='';
  if(item.carousel){
    const slides=item.carousel.map((s,i)=>`<div class="car-slide ${i===0?'on':''}">${s.type==='video'?`<video src="${s.src}" poster="${s.thumb||''}" muted loop playsinline autoplay style="max-width:100%;max-height:66vh;object-fit:contain"></video>`:`<img src="${s.src}" style="max-width:100%;max-height:66vh">`}</div>`).join('');
    const dots=item.carousel.map((_,i)=>`<span class="car-dot ${i===0?'on':''}" data-dot="${i}"></span>`).join('');
    content=`<div class="carousel">${slides}<button class="car-a p">&#8592;</button><button class="car-a n">&#8594;</button><div class="car-ds">${dots}</div></div>`;
  } else if(item.video){
    content=`<video src="${item.video}" poster="${item.img||''}" controls autoplay muted loop playsinline style="max-width:100%;max-height:66vh;object-fit:contain"></video>`;
  } else if(item.img){
    content=`<img src="${item.img}" alt="${item.title}" style="max-width:100%;max-height:66vh;object-fit:contain">`;
  }
  mInner.innerHTML=`
    <div class="m-media">${content}</div>
    <div class="m-info">
      <div class="m-cat">${item.cat||''}</div>
      <h2 class="m-title">${item.title}</h2>
      ${item.sub?`<div class="m-sub">${item.sub}</div>`:''}
      ${item.role?`<div class="m-role">${item.role}</div>`:''}
      ${item.desc?`<p class="m-desc">${item.desc}</p>`:''}
      ${item.link?`<a href="${item.link}" target="_blank" class="m-link">Visit →</a>`:''}
    </div>
  `;
  modal.classList.add('open');
  document.body.style.overflow='hidden';
  // Carousel logic
  if(item.carousel){
    let cur=0;
    const slides=mInner.querySelectorAll('.car-slide');
    const dots=mInner.querySelectorAll('.car-dot');
    function goTo(n){
      slides[cur].classList.remove('on');dots[cur].classList.remove('on');
      cur=(n+slides.length)%slides.length;
      slides[cur].classList.add('on');dots[cur].classList.add('on');
      const v=slides[cur].querySelector('video');
      if(v){mInner.querySelectorAll('video').forEach(vid=>vid.pause());v.play();}
    }
    mInner.querySelector('.car-a.p').addEventListener('click',e=>{e.stopPropagation();goTo(cur-1);});
    mInner.querySelector('.car-a.n').addEventListener('click',e=>{e.stopPropagation();goTo(cur+1);});
    dots.forEach(d=>d.addEventListener('click',e=>{e.stopPropagation();goTo(+d.dataset.dot);}));
  }
}

function closeModal(){
  if(!modal) return;
  modal.classList.remove('open');
  document.body.style.overflow='';
  if(mInner) mInner.querySelectorAll('video').forEach(v=>v.pause());
}

if(mClose) mClose.addEventListener('click',closeModal);
if(modal){
  modal.addEventListener('click',e=>{if(e.target===modal||e.target.classList.contains('m-wrap'))closeModal();});
  window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
}

/* ── ENTER GATE ── */
let entered=false;
function enterSite(e){
  if(e) e.stopPropagation();
  if(entered) return;
  entered=true;
  const gate=document.getElementById('gate');
  const world=document.getElementById('world');
  if(!gate||!world) return;
  gsap.to(gate,{opacity:0,duration:1.4,ease:'power2.inOut',onComplete:()=>{
    gate.style.display='none';
    world.style.display='block';
    world.style.opacity='1';
    startWorld();
  }});
}

const gBtn=document.getElementById('g-btn');
if(gBtn) gBtn.addEventListener('click',enterSite);

/* ── START WORLD ── */
function startWorld(){
  // Build all sections
  buildTools();
  buildProjects();
  buildCreative();
  buildCuratorial();
  buildResearch();
  
  // Build vgrid
  const vgrid=document.getElementById('vgrid');
  if(vgrid){
    b.forEach((p,i)=>{
      if(!p.video) return;
      const vp=document.createElement('div');
      vp.className='vp';
      vp.innerHTML=`<video src="${p.video}" poster="${p.img||''}" muted loop playsinline preload="none"></video><div class="vp-scrim"></div><div class="vp-info"><div class="vp-cat">${p.cat}</div><div class="vp-title">${p.title}</div></div>`;
      vp.addEventListener('mouseenter',()=>vp.querySelector('video').play());
      vp.addEventListener('mouseleave',()=>vp.querySelector('video').pause());
      vp.addEventListener('click',()=>openModal(p));
      vgrid.appendChild(vp);
    });
  }

  // Hero animation
  gsap.to('.h-line',{y:'0%',duration:1.2,ease:'power4.out',stagger:.1,delay:.1});
  gsap.to('.h-eye',{opacity:1,duration:.9,ease:'power3.out',delay:.55});
  gsap.to('.h-stmt',{opacity:1,duration:.9,ease:'power3.out',delay:.7});

  // Scroll-based nav highlight
  window.addEventListener('resize',()=>ST.refresh(),{passive:true});
}
